fn frame(t: i32) {
    host::display::clear(0x0d0d13);
    if host::display::state_get(0) == 0 {
        host::mp::auto(8);
        host::display::state_set(0, 1);
    }
    host::display::draw_string(150, 30, "PRESENCE BOARD", 0xffffff, 2);
    if host::mp::connected() == 0 {
        host::display::draw_string(160, 240, "CONNECTING", 0xaa7700, 2);
    } else {
        host::mp::set(0, host::display::pointer_down());
        let n: i32 = host::mp::peer_count();
        let me: i32 = host::mp::self_index();
        let mut i: i32 = 0;
        while i < 8 {
            let y: i32 = 90 + i * 48;
            host::display::fill_rect(60, y, 392, 40, 0x181c24);
            host::display::draw_string(76, y + 14, "PEER", 0x8899aa, 1);
            host::display::draw_number(116, y + 12, i, 0xffffff, 1);
            if i < n {
                host::display::fill_rect(200, y + 12, 16, 16, 0x22bb44);
                if host::mp::get(i, 0) == 1 {
                    host::display::fill_rect(260, y + 12, 16, 16, 0xffcc33);
                }
            } else {
                host::display::fill_rect(200, y + 12, 16, 16, 0x333333);
            }
            if i == me {
                host::display::draw_string(380, y + 14, "YOU", 0x66aaff, 1);
            }
            i = i + 1;
        }
        host::display::draw_string(60, 486, "GREEN = HERE   GOLD = TOUCHING", 0x556677, 1);
    }
    host::display::present();
}
